{
    public string Name; public float Heat, Cold, Dry, Mist; public bool Under; public int? Turf; public int Grass = 0x86b050;
    public T Top, Sub, Rock; public int SubDepth = 5;
    public (string s, float w)[] Trees = []; public float TreeP = .2f; public int TreeGap = 4;
    public (string s, float p, int kind)[] Plants = [];
    public string Back = "hills"; public int Far, Mid, Near; public string Stamp = "tree";
    public Col SkyTop = new(1, 1, 1), SkyHor = new(1, 1, 1), Sun = new(1, 1, 1), Amb = new(1, 1, 1);
    public Drift Air = Drift.Leaves; public int[] AirCols = [0x8fb050]; public float AirRate = 1; public string Music = "village", Step = "grass";
    public int Shallow = 0x4f9fb4, Deep = 0x1c4a6a; public float LakeP = .5f;
    public string[] Hang = []; public (string s, float p, int lamp, float r)[] CaveFloor = [];
}

